package tui

import (
	"context"
	"log/slog"
	"time"

	"github.com/docker/docker-agent/pkg/app"
	"github.com/docker/docker-agent/pkg/runtime"
	"github.com/docker/docker-agent/pkg/session"
	"github.com/docker/docker-agent/pkg/tui/service/supervisor"
	"github.com/docker/docker-agent/pkg/tui/service/tuistate"
	"github.com/docker/docker-agent/pkg/userconfig"
)

// This file contains the persistence and lookup logic for the multi-tab
// model. The TUI uses two parallel tab identifiers:
//
//   - "runtime tab IDs": ephemeral, generated by the supervisor for the live
//     session of an open tab.
//   - "persisted session IDs": stable session-store IDs that survive
//     restarts and are stored in tuistate.
//
// pendingRestores bridges the two until a tab is lazily loaded on first
// switch.

// persistActiveTab writes the active tab ID to the tuistate store.
func (m *appModel) persistActiveTab(persistedID string) {
	if m.tuiStore == nil || m.restoringTabs {
		return
	}
	if err := m.tuiStore.SetActiveTab(m.ctx(), persistedID); err != nil {
		slog.Warn("Failed to set active tab", "error", err)
	}
}

// persistFreshTab clears the tab store and writes a single initial tab.
func (m *appModel) persistFreshTab(ctx context.Context, sessionID, workingDir string) {
	if m.tuiStore == nil {
		return
	}
	if err := m.tuiStore.ClearTabs(ctx); err != nil {
		slog.WarnContext(ctx, "Failed to clear tabs", "error", err)
	}
	if err := m.tuiStore.AddTab(ctx, sessionID, workingDir); err != nil {
		slog.WarnContext(ctx, "Failed to persist initial tab", "error", err)
	}
	if err := m.tuiStore.SetActiveTab(ctx, sessionID); err != nil {
		slog.WarnContext(ctx, "Failed to set active tab", "error", err)
	}
	if err := m.tuiStore.SetPaneWorkspaceState(ctx, tuistate.PaneWorkspaceState{
		Version: 1, ActiveAnchorSessionID: sessionID,
		Workspaces: []tuistate.PaneWorkspace{{
			AnchorSessionID: sessionID, FocusSessionID: sessionID,
			Layout: &tuistate.PaneLayoutNode{SessionID: sessionID},
		}},
	}); err != nil {
		slog.WarnContext(ctx, "Failed to reset pane workspace state", "error", err)
	}
}

// restoreTabs restores previously persisted tabs (if enabled) or persists the
// initial session as the sole tab. The tuistate DB always stores persisted
// session-store IDs. Runtime tab/routing IDs are ephemeral; the pendingRestores
// map bridges the two:  pendingRestores[runtimeTabID] = persistedSessionID.
func (m *appModel) restoreTabs(
	ctx context.Context,
	ts *tuistate.Store,
	sv *supervisor.Supervisor,
	spawner SessionSpawner,
	initialApp *app.App,
	initialTabID, initialWorkingDir string,
) {
	if ts == nil {
		return
	}

	var savedTabs []tuistate.TabEntry
	var savedActiveID string
	if userconfig.Get().GetRestoreTabs() {
		var err error
		savedTabs, savedActiveID, err = ts.GetTabs(ctx)
		if err != nil {
			slog.WarnContext(ctx, "Failed to read saved tabs", "error", err)
			return
		}
	}

	if len(savedTabs) == 0 {
		m.persistFreshTab(ctx, initialTabID, initialWorkingDir)
		return
	}

	var deferred map[string]runtime.SessionSummaryEntry
	if m.savedTabEntries != nil && m.sessionRestorer != nil && len(savedTabs) > 1 {
		started := time.Now()
		entries, err := m.savedTabEntries(ctx)
		slog.DebugContext(ctx, "Session presentation timing", "phase", "saved_tab_catalog", "elapsed", time.Since(started), "ok", err == nil)
		if err == nil {
			deferred = make(map[string]runtime.SessionSummaryEntry, len(entries))
			for _, row := range entries {
				deferred[row.SessionID] = row
			}
		}
	}
	// Multi-pane workspaces need all their members to restore split geometry.
	// Single-view background tabs have no reason to hydrate before selection.
	var eager map[string]bool
	if deferred != nil {
		eager = savedSplitTabs(ctx, ts)
	}
	sessionStore := initialApp.SessionStore()
	var summaries map[string]session.Summary
	if sessionStore != nil && m.sessionRestorer == nil {
		if rows, err := sessionStore.GetSessionSummaries(ctx); err == nil {
			summaries = make(map[string]session.Summary, len(rows))
			for _, row := range rows {
				summaries[row.ID] = row
			}
		}
	}
	initialSaved := false
	for _, saved := range savedTabs {
		initialSaved = initialSaved || saved.SessionID == initialApp.Session().ID
	}
	initial := initialApp.Session()
	reuseInitial := !initialSaved && initial.Title == "" && len(initial.Messages) == 0
	restoredFirst := false
	restoredCount := 0

	for _, saved := range savedTabs {
		// Startup presence/title checks use one metadata read, never per-tab
		// transcript loads or persisted canonical owner admission.
		if summaries != nil && saved.SessionID != "" && saved.SessionID != initial.ID {
			if _, exists := summaries[saved.SessionID]; !exists {
				continue
			}
		}

		// Restore from saved identities, never by creating placeholder sessions
		// on the managed server.
		if m.sessionRestorer != nil {
			runtimeID := initialTabID
			if saved.SessionID != initialApp.Session().ID {
				row, accessible := deferred[saved.SessionID]
				if deferred != nil && !accessible {
					continue
				}
				if accessible && saved.SessionID != savedActiveID && !eager[saved.SessionID] {
					header := session.New(session.WithID(row.SessionID), session.WithWorkingDir(row.WorkingDir), session.WithTitle(row.Title))
					var err error
					runtimeID, err = sv.AddSession(ctx, nil, header, row.WorkingDir, nil)
					if err != nil {
						continue
					}
					m.pendingRestores[runtimeID] = saved.SessionID
				} else {
					started := time.Now()
					spawned, err := m.sessionRestorer(ctx, saved.SessionID, saved.WorkingDir)
					if m.savedTabEntries != nil {
						slog.DebugContext(ctx, "Session presentation timing", "phase", "restore_saved_tab", "elapsed", time.Since(started), "selected", saved.SessionID == savedActiveID, "ok", err == nil)
					}
					if err != nil {
						slog.WarnContext(ctx, "Failed to restore remote tab", "session_id", saved.SessionID, "error", err)
						continue
					}
					if spawned.App == nil || spawned.Session == nil || spawned.Session.ID != saved.SessionID || spawned.App.Session() == nil || spawned.App.Session().ID != saved.SessionID {
						if spawned.App != nil {
							spawned.App.Close()
						}
						if spawned.Ownership == RuntimeOwned && spawned.Cleanup != nil {
							spawned.Cleanup()
						}
						slog.WarnContext(ctx, "Invalid restored session identity", "session_id", saved.SessionID)
						continue
					}
					cleanup := spawned.Cleanup
					if spawned.Ownership == RuntimeBorrowed {
						cleanup = nil
					}
					runtimeID, err = sv.AddSession(ctx, spawned.App, spawned.Session, spawned.Session.WorkingDir, cleanup)
					if err != nil {
						spawned.App.Close()
						if cleanup != nil {
							cleanup()
						}
						continue
					}
				}
			}
			if runtimeID == initialTabID {
				sv.ReorderTab(0, restoredCount)
			}
			restoredCount++
			restoredFirst = true
			if saved.SidebarCollapsed {
				m.pendingSidebarCollapsed[runtimeID] = true
			}
			if saved.SessionID == savedActiveID {
				m.pendingActiveTab = runtimeID
			}
			continue
		}

		// A saved current session must not become another tab's placeholder.
		var runtimeID string
		if saved.SessionID == initial.ID {
			runtimeID = initialTabID
		} else if sessionStore == nil {
			continue
		} else if !restoredFirst && reuseInitial {
			runtimeID = initialTabID
		} else {
			if spawner == nil {
				continue
			}
			spawned, err := spawner(ctx, saved.WorkingDir)
			if err != nil {
				slog.WarnContext(ctx, "Failed to restore tab", "working_dir", saved.WorkingDir, "error", err)
				continue
			}
			cleanup := spawned.Cleanup
			if spawned.Ownership == RuntimeBorrowed {
				cleanup = nil
			}
			runtimeID, err = sv.AddSession(ctx, spawned.App, spawned.Session, saved.WorkingDir, cleanup)
			if err != nil {
				slog.WarnContext(ctx, "Failed to supervise restored tab", "session_id", saved.SessionID, "error", err)
				continue
			}
		}

		restoredFirst = true
		if runtimeID == initialTabID {
			sv.ReorderTab(0, restoredCount)
		}
		restoredCount++
		// Already attached current sessions need no lazy replacement.
		if saved.SessionID != initial.ID {
			m.pendingRestores[runtimeID] = saved.SessionID
		}
		if saved.SidebarCollapsed {
			m.pendingSidebarCollapsed[runtimeID] = true
		}

		// If this was the active tab, queue a switch on Init().
		if saved.SessionID == savedActiveID {
			m.pendingActiveTab = runtimeID
		}

		if summary, exists := summaries[saved.SessionID]; exists && summary.Title != "" {
			sv.SeedTitle(runtimeID, summary.Title)
		}
	}

	// An unsaved blank is only a fallback view, not another tab to retry.
	if !initialSaved && m.pendingRestores[initialTabID] == "" && initialApp.AttachedSubagent() == nil {
		m.fallbackTab = initialTabID
	}
	if m.fallbackTab != "" && (initial.Title != "" || len(initial.Messages) != 0) {
		if err := ts.AddTab(ctx, initial.ID, initialWorkingDir); err != nil {
			slog.WarnContext(ctx, "Failed to persist current tab", "error", err)
		} else {
			m.fallbackTab = ""
		}
	}
}

func savedSplitTabs(ctx context.Context, store *tuistate.Store) map[string]bool {
	state, err := store.GetPaneWorkspaceState(ctx)
	if err != nil || state.Version > 1 {
		return nil
	}
	tabs := make(map[string]bool)
	for _, workspace := range state.Workspaces {
		members := make(map[string]bool)
		var collect func(*tuistate.PaneLayoutNode)
		collect = func(node *tuistate.PaneLayoutNode) {
			if node == nil {
				return
			}
			if node.SessionID != "" {
				members[node.SessionID] = true
			}
			collect(node.First)
			collect(node.Second)
		}
		collect(workspace.Layout)
		collect(workspace.RestoreLayout)
		if len(members) > 1 {
			for id := range members {
				tabs[id] = true
			}
		}
	}
	return tabs
}

// persistedSessionID returns the session-store ID that should be used for
// tuistate persistence for the given runtime tab ID.
//
// If the tab has a pending restore (session not yet lazily loaded), the
// persisted ID from pendingRestores is returned — this is the original
// session-store ID that was saved across restarts. Otherwise the live
// session ID from the app is used.
func (m *appModel) persistedSessionID(tabID string) string {
	if persistedID, ok := m.pendingRestores[tabID]; ok {
		return persistedID
	}
	if runner := m.supervisor.GetRunner(tabID); runner != nil && runner.App != nil {
		return runner.App.Session().ID
	}
	return tabID
}

// findTabByPersistedID scans all open tabs and returns the runtime tab ID
// whose persisted session-store ID matches the given ID. Returns "" if not found.
func (m *appModel) findTabByPersistedID(persistedID string) string {
	// Check pending restores first (tabs not yet lazily loaded).
	for tabID, pid := range m.pendingRestores {
		if pid == persistedID {
			return tabID
		}
	}
	// Check live sessions.
	tabs, _ := m.supervisor.GetTabs()
	for _, tab := range tabs {
		if runner := m.supervisor.GetRunner(tab.SessionID); runner != nil && runner.App != nil {
			if runner.App.Session().ID == persistedID {
				return tab.SessionID
			}
		}
	}
	return ""
}

// persistTabOrder reorders visible tabs without moving inaccessible saved slots.
func (m *appModel) persistTabOrder(ids []string) error {
	saved, _, err := m.tuiStore.GetTabs(m.ctx())
	if err != nil {
		return err
	}
	persisted := make(map[string]bool, len(saved))
	for _, tab := range saved {
		persisted[tab.SessionID] = true
	}
	visible := make(map[string]bool, len(ids))
	var live []string
	for _, id := range ids {
		if persisted[id] {
			visible[id] = true
			live = append(live, id)
		}
	}
	var order []string
	next := 0
	for _, tab := range saved {
		if visible[tab.SessionID] {
			order = append(order, live[next])
			next++
		} else {
			order = append(order, tab.SessionID)
		}
	}
	return m.tuiStore.ReorderTab(m.ctx(), order)
}

func (m *appModel) persistFallbackTab() {
	if m.tuiStore == nil {
		return
	}
	focus := m.paneFocus()
	if m.pendingRestores[focus] != "" {
		// Typing into a failed placeholder starts a new conversation, not a
		// replacement for the saved identity that could not be loaded.
		delete(m.pendingRestores, focus)
		delete(m.pendingSidebarCollapsed, focus)
		m.fallbackTab = focus
	}
	if m.fallbackTab == "" || m.fallbackTab != focus {
		return
	}
	runner := m.supervisor.GetRunner(m.fallbackTab)
	if runner == nil || runner.App == nil {
		return
	}
	id := runner.App.Session().ID
	if err := m.tuiStore.AddTab(m.ctx(), id, runner.WorkingDir); err != nil {
		slog.Warn("Failed to persist fallback tab", "error", err)
		return
	}
	m.fallbackTab = ""
	m.persistActiveTab(id)
	m.persistPaneWorkspaceState()
}
